// The admin console (docs/47), built and served by the plain gateway at
// /dashboard/console.html, on a database seeded for this run by e2e/console_server.py. The
// passwords were generated by playwright.config.ts at the start of the run.

import { expect, test, type Locator, type Page } from "@playwright/test";

test.describe.configure({ mode: "serial" });

function secret(name: string): string {
  const value = process.env[name];
  if (value === undefined || value === "") {
    throw new Error(`${name} is not set: run the console tests through playwright.config.ts`);
  }
  return value;
}

interface Account {
  username: string;
  first: () => string;
  password: () => string;
}

function account(username: string, variable: string): Account {
  return {
    username,
    first: () => secret(`CONSOLE_E2E_${variable}_FIRST_PASSWORD`),
    password: () => secret(`CONSOLE_E2E_${variable}_PASSWORD`),
  };
}

const ADMIN = account("admin-e2e", "ADMIN");
const VIEWER = account("viewer-e2e", "VIEWER");
const APP_ADMIN = account("appadmin-e2e", "APPADMIN");

/** An account's first login: the console asks for a new password before anything else. */
async function firstLogIn(page: Page, who: Account) {
  await page.goto("/dashboard/console.html");
  const form = page.getByRole("region", { name: "Log in" });
  await form.getByLabel("Username").fill(who.username);
  await form.getByLabel("Password").fill(who.first());
  await form.getByRole("button", { name: "Log in" }).click();
  const change = page.getByRole("region", { name: "Change your password" });
  await change.getByLabel("Current password").fill(who.first());
  await change.getByLabel("New password").fill(who.password());
  await change.getByRole("button", { name: "Change password" }).click();
  await expect(page.getByRole("heading", { name: "Application settings" })).toBeVisible();
}

async function logIn(page: Page, account: Account) {
  await page.goto("/dashboard/console.html");
  const form = page.getByRole("region", { name: "Log in" });
  await form.getByLabel("Username").fill(account.username);
  await form.getByLabel("Password").fill(account.password());
  await form.getByRole("button", { name: "Log in" }).click();
  await expect(page.getByRole("button", { name: "Log out" })).toBeVisible();
}

async function openApplication(page: Page, label: string): Promise<void> {
  await page.getByRole("combobox", { name: "Application", exact: true }).selectOption({ label });
  await expect(page.getByRole("region", { name: "Settings in force" })).toBeVisible();
}

function row(region: Locator, name: string): Locator {
  return region
    .getByRole("row")
    .filter({ has: region.page().getByRole("rowheader", { name, exact: true }) });
}

async function change(page: Page, setting: string, mode: "keep" | "set" | "unset", value?: string) {
  const edit = page.getByRole("region", { name: "Edit" });
  await edit.getByLabel(`${setting}: change`).selectOption(mode);
  if (value !== undefined) await edit.getByLabel(`${setting}: value`).fill(value);
}

/** The buttons and form fields that change something, inside the screen (not the header). */
async function writeControls(page: Page): Promise<number> {
  const main = page.getByRole("main");
  const buttons = main.getByRole("button", { name: /^(Save|Apply |Revert|Confirm)/ });
  const fields = main.getByRole("region", { name: "Edit" });
  return (await buttons.count()) + (await fields.count());
}

test("the login screen refuses a wrong password, opens the console, and runs no inline script", async ({
  page,
}) => {
  const problems: string[] = [];
  page.on("pageerror", (error) => problems.push(error.message));
  page.on("console", (message) => {
    if (message.type() === "error") problems.push(message.text());
  });

  // The page as served: every script a file of the gateway's, none inline.
  const html = await (await page.request.get("/dashboard/console.html")).text();
  expect(html).toMatch(/<script[^>]*\bsrc="\/dashboard\/assets\//);
  expect(html).not.toMatch(/<script(?![^>]*\bsrc=)[^>]*>/);

  await page.goto("/dashboard/console.html");
  // Its policy, before any script: scripts and styles from the gateway only, never inline.
  const policy = await page
    .locator('head > meta[http-equiv="Content-Security-Policy"]:first-child')
    .getAttribute("content");
  expect(policy).toContain("default-src 'none'");
  expect(policy).toContain("script-src 'self'");
  expect(policy).toContain("style-src 'self'");
  expect(policy).not.toContain("unsafe-inline");
  const form = page.getByRole("region", { name: "Log in" });
  await form.getByLabel("Username").fill(ADMIN.username);
  await form.getByLabel("Password").fill(`${ADMIN.first()}-wrong`);
  await form.getByRole("button", { name: "Log in" }).click();
  await expect(form.getByRole("alert")).toBeVisible();
  await expect(page.getByRole("button", { name: "Log out" })).toHaveCount(0);

  await firstLogIn(page, ADMIN);
  // The refused login's 401s are the only errors the browser reports; nothing was blocked.
  expect(problems.filter((p) => !p.includes("401"))).toEqual([]);
});

test("each account's first login asks for a new password before anything else", async ({
  page,
}) => {
  await firstLogIn(page, VIEWER);
  await page.getByRole("button", { name: "Log out" }).click();
  await firstLogIn(page, APP_ADMIN);
  await page.getByRole("button", { name: "Log out" }).click();
  // The new password is the one that works now.
  await logIn(page, ADMIN);
});

test("application settings: in force and why, checked edits, step-up when loosening, history, revert, presets", async ({
  page,
}) => {
  await logIn(page, ADMIN);
  await openApplication(page, "App one (app-one)");
  await expect(page.getByText("May change")).toBeVisible();

  const inForce = page.getByRole("region", { name: "Settings in force" });
  await expect(row(inForce, "requests_per_minute")).toContainText("600");
  await expect(row(inForce, "requests_per_minute")).toContainText("organization");

  // A tightening change: checked by the gateway, saved with no password.
  const verdict = page.getByRole("status", { name: "Check result" });
  await change(page, "max_hosted_attempts", "set", "1");
  await expect(verdict).toContainText("Valid. Changes: max_hosted_attempts.");
  await expect(verdict).not.toContainText("asks for your password");
  await page.getByRole("button", { name: "Save" }).click();
  await expect(page.getByText("Saved as version 1.")).toBeVisible();
  await expect(page.getByRole("dialog")).toHaveCount(0);

  // Looser than the organization's cap: refused by the dry run, not offered.
  await change(page, "requests_per_minute", "set", "5000");
  await expect(verdict).toContainText("Refused");
  await expect(page.getByRole("button", { name: "Save" })).toBeDisabled();
  await change(page, "requests_per_minute", "keep");

  // Loosening where prompts go: the dry run says so, and Save asks for the password.
  await change(page, "max_hosted_attempts", "unset");
  await expect(verdict).toContainText("saving asks for your password");
  await page.getByRole("button", { name: "Save" }).click();
  const dialog = page.getByRole("dialog", { name: "Confirm with your password" });
  await dialog.getByLabel("Password").fill(ADMIN.password());
  await dialog.getByRole("button", { name: "Confirm" }).click();
  await expect(page.getByText("Saved as version 2.")).toBeVisible();
  await expect(page.getByRole("dialog")).toHaveCount(0);

  const history = page.getByRole("region", { name: "History" });
  await expect(history.getByRole("row")).toHaveCount(3); // the header and two versions
  await expect(history).toContainText("max_hosted_attempts");

  // Back to version 1's values, which tightens: no password.
  await history.getByRole("button", { name: "Revert to the previous version" }).click();
  await expect(page.getByText("Reverted as version 3.")).toBeVisible();
  await expect(row(inForce, "max_hosted_attempts")).toContainText("1");

  // The presets, with their exact values; applying one is a version like any other.
  const presets = page.getByRole("region", { name: "Presets" });
  await expect(presets).toContainText('["economy"]');
  await presets.getByRole("button", { name: "Apply private" }).click();
  await expect(page.getByText("Applied private as version 4.")).toBeVisible();
});

test("organization settings: the caps, the applications each one limits, the history", async ({
  page,
}) => {
  await logIn(page, ADMIN);
  await page.getByRole("link", { name: "Organization settings" }).click();
  const caps = page.getByRole("region", { name: "Caps" });
  await expect(row(caps, "requests_per_minute")).toContainText("600");
  const limits = page.getByRole("region", { name: "Applications each cap limits" });
  await expect(row(limits, "requests_per_minute")).toContainText("App one, App two");
  const history = page.getByRole("region", { name: "History" });
  await expect(history).toContainText("the operator (CLI)");
  await expect(history).toContainText("cli");
  // This screen shows; it changes nothing, for any account.
  expect(await writeControls(page)).toBe(0);
});

test("a viewer sees no write controls on either screen", async ({ page }) => {
  await logIn(page, VIEWER);
  await openApplication(page, "App one (app-one)");
  await expect(page.getByText("Read only")).toBeVisible();
  await expect(page.getByRole("region", { name: "Presets" })).toContainText("cheap");
  expect(await writeControls(page)).toBe(0);
  await expect(page.getByRole("main").getByRole("textbox")).toHaveCount(0);

  await page.getByRole("link", { name: "Organization settings" }).click();
  await expect(page.getByRole("region", { name: "Caps" })).toBeVisible();
  expect(await writeControls(page)).toBe(0);
});

test("an application's own admin names its application and cannot read the organization's caps", async ({
  page,
}) => {
  await logIn(page, APP_ADMIN);
  await page.getByLabel("Application id").fill("app-one");
  await page.getByRole("button", { name: "Open" }).click();
  await expect(page.getByText("May change")).toBeVisible();
  await expect(page.getByRole("region", { name: "Edit" })).toBeVisible();

  await page.getByRole("link", { name: "Organization settings" }).click();
  await expect(page.getByRole("alert")).toHaveText("Not permitted, or not found.");
});

test("leak scan: no password or CSRF token is kept in storage, the page, the URL or the console", async ({
  page,
}) => {
  const sent: string[] = [];
  const answered: string[] = [];
  const consoleLines: string[] = [];
  page.on("request", (request) => sent.push(request.postData() ?? ""));
  page.on("response", (response) => {
    if (response.url().endsWith("/v1/auth/login")) {
      void response.text().then((text) => answered.push(text));
    }
  });
  page.on("console", (message) => consoleLines.push(message.text()));

  // Log in, and make a change that needs a step-up, on the other application.
  await logIn(page, ADMIN);
  await openApplication(page, "App two (app-two)");
  await change(page, "max_hosted_attempts", "set", "1");
  await expect(page.getByRole("status", { name: "Check result" })).toContainText("Valid.");
  await page.getByRole("button", { name: "Save" }).click();
  await expect(page.getByText("Saved as version 1.")).toBeVisible();
  await change(page, "max_hosted_attempts", "unset");
  await expect(page.getByRole("status", { name: "Check result" })).toContainText("password");
  await page.getByRole("button", { name: "Save" }).click();
  const dialog = page.getByRole("dialog", { name: "Confirm with your password" });
  await dialog.getByLabel("Password").fill(ADMIN.password());
  await dialog.getByRole("button", { name: "Confirm" }).click();
  await expect(page.getByText("Saved as version 2.")).toBeVisible();

  const login = JSON.parse(answered[0] ?? "{}") as { csrf_token?: string };
  const csrf = login.csrf_token ?? "";
  const password = ADMIN.password();

  // The control: both planted values are found where they must be, so the scan can see them.
  expect(csrf.length).toBeGreaterThan(10);
  expect(sent.some((body) => body.includes(password))).toBe(true);
  expect(answered.join("")).toContain(csrf);

  // Everything the browser keeps or shows.
  const kept = await page.evaluate(async () => {
    const dump = (storage: Storage) =>
      Array.from({ length: storage.length }, (_, i) => {
        const key = storage.key(i) ?? "";
        return `${key}=${storage.getItem(key) ?? ""}`;
      }).join("\n");
    const databases = await indexedDB.databases();
    return {
      local: dump(localStorage),
      session: dump(sessionStorage),
      cookie: document.cookie,
      inputs: Array.from(document.querySelectorAll("input"), (input) => input.value).join("\n"),
      databases: databases.map((d) => d.name ?? "").join("\n"),
    };
  });
  const places = {
    ...kept,
    page: await page.content(),
    url: page.url(),
    console: consoleLines.join("\n"),
  };
  for (const [place, text] of Object.entries(places)) {
    expect(text.includes(password), `password in ${place}`).toBe(false);
    expect(text.includes(csrf), `CSRF token in ${place}`).toBe(false);
  }
  // The session cookie is HttpOnly: no script sees it. Only the theme is stored.
  expect(kept.cookie).toBe("");
  expect(kept.session).toBe("");
  expect(kept.local === "" || kept.local.startsWith("gateway-dashboard-theme=")).toBe(true);
});
